def life_step(grid):
    rows = len(grid)
    cols = len(grid[0])
    new_grid = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            live_neighbors = sum(grid[nr][nc] for nr, nc in neighbors(grid, r, c) if 0 <= nr < rows and 0 <= nc < cols)

            if grid[r][c]:
                if live_neighbors in (2, 3):
                    new_grid[r][c] = True
            else:
                if live_neighbors == 3:
                    new_grid[r][c] = True

    return new_grid

